["WeaponsDesc1BP_ColPer_EyeOfTruth"] = "[ТЕКСТ ПОВРЕЖДЕН] УЗРИ ТО ЧТО ВИЖУ Я [ТЕКСТ ПОВРЕЖДЕН] ОБИТЕЛЬ БОЛИ [ТЕКСТ ПОВРЕЖДЕН] В МОИХ ВЛАДЕНИЯХ ДОЗВОЛЕНО ВСЕ\n\n<n2>ВНИМАНИЕ: объект внедрился в [НЕИЗВЕСТНАЯ ОШИБКА] системы. Извлечение невозможно без полного отключения системы.</>",
["LocalizedKeyValues_ERROR"] = "[ОШИБКА]",
["EnemiesDesc2BP_TTBoss_VirtualEntry"] = "[НЕВЕДОМЫЙ УЖАС] отправил зашифрованный сигнал.\n\n<n12>ä ӼψȥЄֿ͈ȃыӉۉ Ԅҥ|</><n2>ВЕРДИКТ IS</><n12>ŷҵڐʘƯјؙˬӞъΏ٧ èǍȜĮ</><n2>ЗАПРЕТНО</><n12>ԄӁû ŊʘםۧԄ ϽӉ͠ъȜè؟üŴ ؎͚ɂٱҖƥûבɗʊЈ֦</><n2>ОБЪЯТИЯ ЗАВЕРШАЮТСЯ</><n12>ۼŊқ Єֿ͈ ӳǜڐˬ ٱЈȃ Ӊ ȈӺШٱŴ Įۉʃŕ ǆ ɋҠǍӼјؙȥ ˧̅ć¨ъ֦</><n2>ПАРАЛИЧ</><n12>ӳʘϔ äɗ ϔڐȥדǆûŴ Ëû¬ҵƯ ɋψ ǆʘבчΏ ʩӉ͠ Ͻü</><n2>ХОЛОДНЫЙ ПОЗВОНОЧНЫЙ</><n12>ѭ ǆ ہŊ ɂǍȥъŷûҖ</>\n\nСигнал частично расшифрован.\n\n\n\\ «Вердикт — невинность. Никакого освобождения.\nПустые объятия завершаются и начинаются вновь.\"\n\nДля дальнейшего анализа необходимы [ОШИБКА ОБРАТНОЙ СВЯЗИ].",
["EnemiesDesc3BP_TTBoss_VirtualEntry"] = "[НЕВЕДОМЫЙ УЖАС] отправил зашифрованный сигнал.\n\n<n12>äӼψȥЄֿ͈ȃы ӉۉԄҥ|</><n2>ВЕРДИКТ IS</><n12>ŷҵڐ ʘƯјؙˬӞ ъΏ٧èǍ ȜĮ</><n2>ЗАПРЕТНО</><n12>ԄӁûŊʘםۧԄϽӉ͠ъȜè؟üŴ؎͚ɂٱҖƥûבɗʊЈ֦</><n2>ОБЪЯТИЯ ЗАВЕРШАЮТСЯ</><n12>ۼŊқЄֿ͈ӳǜڐˬٱЈȃӉ ȈӺШٱŴĮۉʃ ŕǆɋҠǍӼјؙȥ˧̅ć¨ъ֦</><n2>ПАРАЛИЧ</><n12>ӳʘϔä ɗϔڐȥדǆûŴËû¬ҵƯ ɋψǆʘבчΏʩ Ӊ͠Ͻü</><n2>ХОЛОДНЫЙ ПОЗВОНОЧНЫЙ</><n12>ѭǆ ہŊɂǍȥъŷ ûҖ</>\n\nСигнал частично расшифрован.\n\n\\ «Вердикт — невинность. Никакого освобождения.\nПустые объятия завершаются и начинаются вновь.\"\n\nСигнал полностью расшифрован.\n\n#~/>,наблюдает, постоянно наблюдает подернутыми пеплом глазами, неспособными видеть по-настоящему. Ее датчики предупредили о приближении, и она поняла, что нужно делать, но не могла пошевелиться, окруженная и скованная ледяными потоками позвоночного геля, бегущими по~''#/",
["EnemiesDesc1BP_TTBoss_VirtualEntry"] = "[НЕВЕДОМЫЙ УЖАС] отправил зашифрованный сигнал.\n\n<n12>äӼψȥЄֿ͈ȃыӉۉԄҥ|</><n2>ВЕРДИКТ IS</><n12>ŷҵڐʘƯјؙˬӞъΏ٧èǍȜĮ</><n2>ЗАПРЕТНО</><n12>ԄӁûŊʘםۧԄϽӉ͠ъȜè؟üŴ؎͚ɂٱҖƥûבɗʊЈ֦</><n2>ОБЪЯТИЯ ЗАВЕРШАЮТСЯ</><n12>ۼŊқЄֿ͈ӳǜڐˬٱЈȃӉȈӺШٱŴĮۉʃŕǆɋҠǍӼјؙȥ˧̅ć¨ъ֦</><n2>ПАРАЛИЧ</><n12>ӳʘϔäɗϔڐȥדǆûŴËû¬ҵƯɋψǆʘבчΏʩӉ͠Ͻü</><n2>ХОЛОДНЫЙ ПОЗВОНОЧНЫЙ</><n12>ѭǆہŊɂǍȥъŷûҖ</>\n\nДля дальнейшего анализа необходимы [ОШИБКА ОБРАТНОЙ СВЯЗИ].",
["EnemiesDesc3BP_ReaperBoss_VirtualEntry"] = "[НЕВЕДОМЫЙ УЖАС] отправил зашифрованный сигнал.\n\n<n12>ƪΓϸӎƵ§ЩǱؕ </> <n2>ВНУТРИ</> <n12>ݹтԺԲғӨ</> <n12>ɿɩٻĪ۹ہ̰ǜʗи</> <n2>НЕЧЕГО</> <n12>ĈƄωЄҖرŕ٧ڠձӳ%¤|ä! Įٱƥŷćҵȥ¬ǆבʡû</> <n2>МОЛЧАЛИВАЯ ТЯЖЕСТЬ</> <n12>ѣĮٱƥŷćҵȥһՅǆԿʡǍŊӼüɁä¨'§ΏʃϽ˞ъ ϸω</> <n2>УЖЕ</> <n12>ВчȜ٤ˁӁ²ϔƯҠԄ؟ɳըټφҖرŕ٧ڠձӳѣ</> <n2>СВЯТОСТЬ</> <n12>Įƥŷćҵ͘בʡÈǜʡǍŊӉ͠Ӟ</>\n\nСигнал частично расшифрован.\n\n«Открывается внутри. Может закончиться.\n\nАванкамера глубины. Больше не с чем сравнивать».\n\nСигнал полностью расшифрован.\n\n^]#]угли тлеют, разжигать нечего. Она поворошила их. Колыхнулся ленивый оранжевый язык, но молчаливая тяжесть холодного воздуха машинного зала придушила и его. Она с шумом вдохнула, приготовившись объясняться, но он уже уходил. Сожаление или долг, святость или*#;\\}",
