["PCConsumable.Text"] = "<n2>НАЖМИТЕ</> <button>{Action_Consumable1}</>, чтобы использовать.\r\n\r\n<n1>Расходниками</> называются одноразовые предметы с уникальными эффектами. У вас может быть несколько копий одного и того же <n1>расходника</>.\r\n\r\nОткройте снаряжение, чтобы узнать больше о добытых <n1>расходниках</>.",
["PCConsumableSlot.Text"] = "<n2>НАЖМИТЕ</> <button>{Action_Consumable1}</> или <button>{Action_Consumable2}</>, чтобы использовать расходник.",
["Consumable.Text"] = "<n2>НАЖМИТЕ</> <button>{Action_Consume}</>, чтобы использовать.\n\n<n1>Расходниками</> называются одноразовые предметы с уникальными эффектами. У вас может быть несколько копий одного и того же <n1>расходника</>.\n\nОткройте снаряжение, чтобы больше узнать о добытых <n1>расходниках</>.",
["Dash.Text"] = "<n2>НАЖМИТЕ</> <button>{Action_Evasion}</>, чтобы совершить рывок.\n<n2>УДЕРЖИВАЙТЕ</> <button>{Action_Evasion}</>, чтобы совершить рывок на большее расстояние.\n\nЧтобы прыгнуть дальше, совершите рывок в воздухе.\n\nВо время рывка вы не получаете урона опасного воздействия среды и большинства вражеских атак.",
["Dash.TextPC"] = "<n2>{ActionType_Evasion}</> <button>{Action_Evasion}</>, чтобы совершить рывок.\r\n<n2>{ActionType_Hold_Evasion}</> <button>{Action_Evasion}</>, чтобы совершить рывок на большее расстояние.\r\n\r\nЧтобы прыгнуть дальше, совершите рывок в воздухе.\r\n\r\nВо время рывка вы не получаете урона опасного воздействия среды и большинства вражеских атак.",
["AltFire.TextSimple"] = "<n2>УДЕРЖИВАЙТЕ</> <button>{Action_AltFire}</> и <n2>НАЖМИТЕ</> <button>{Action_FireTrigger}</>, чтобы использовать <n1>альтернативный огонь</>.\n\nИспользуйте <n1>альтернативный огонь</>, чтобы уничтожить нарост на вратах.",
["AltFire.Text3"] = "<n2>НАЖМИТЕ</> <button>{Action_FireTrigger}</>, одновременно удерживая <button>{Action_AltFire}</>.\n\nИспользуйте <n1>альтернативный огонь</>, чтобы уничтожить нарост на вратах.",
["Jump.Text"] = "<n2>Нажмите</> <button>{Action_Jump}</>, чтобы прыгнуть.",
["Jump.TextPC"] = "<n2>{ActionType_Jump}</> <button>{Action_Jump}</>, чтобы прыгнуть.",
["Melee.Text"] = "<n2>НАЖМИТЕ</> <button>{Action_Melee}</> для атаки в ближнем бою.\n\nИспользуйте удары ближнего боя, чтобы атаковать врагов, уничтожать барьеры и препятствия.",
["PCMelee.Text"] = "<n2>{ActionType_Melee}</> <button>{Action_Melee}</>, чтобы атаковать в ближнем бою.\r\n\r\nИспользуйте удары ближнего боя, чтобы атаковать врагов, уничтожать барьеры и препятствия.",
["PCNominateConsumable.Text"] = "<n2>{ActionType_NominateConsumable}</> <button>{Action_NominateConsumable}</>, чтобы выбрать, какой расходник заменится.",
["OpenMenu.Text"] = "<n2>НАЖМИТЕ</> <button>{Action_PauseGame}</>, чтобы открыть экран компьютера скафандра.\n\nПросмотр карты, состояния скафандра, снаряжения и хранилища данных.",
["OpenMenu.TextPC"] = "<button>{Action_PauseGame}</> <n2>{ActionType_PauseGame}</>, чтобы открыть экран компьютера скафандра.\n\nПросмотр карты, состояния скафандра, снаряжения и хранилища данных.",
["PCNominateConsumable.GamepadText"] = "<n2>{ActionType_PocketLeft}</> <button>{Action_PocketLeft}</><n2> или </><button>{Action_PocketRight}</>, чтобы выбрать, какой расходник заменится.",
["PCTutorial.HowToChangeControllerPreset"] = "<n2>НАЖМИТЕ</> <button>{Action_SystemMenu}</>, чтобы изменить предустановку контроллера.",
["PCSuperWeaponDesc.Text"] = "<n1>Экстракторы</> — это мощные боевые расходники, временно заменяющие ваше основное оружие. Подберите <n1>экстрактор</> нового типа, чтобы конвертировать все имеющиеся у вас <n1>экстракторы</> в этот тип.\r\n\r\n<n2>НАЖМИТЕ</> <button>{Action_Consumable1}</>, <button>{Action_Consumable2}</> или <button>{Action_Consumable3}</>, чтобы использовать экстрактор, и <button>{Action_FireTrigger}</>, чтобы выстрелить.",
["SuperWeaponDesc.Text"] = "<n1>Экстракторы</> — это мощные боевые расходники, временно заменяющие ваше основное оружие. Подберите <n1>экстрактор</> нового типа, чтобы конвертировать все имеющиеся у вас <n1>экстракторы</> в этот тип.\n\n<button>{Action_Consume}</> <n2>НАЖМИТЕ</>, чтобы использовать, и <button>{Action_FireTrigger}</>, чтобы выстрелить.",
["Movement.SprintText"] = "<n2>УДЕРЖИВАЙТЕ</> <text></><text> при движении, чтобы бежать.</>",
["Movement.LookText"] = "<n2>ИСПОЛЬЗУЙТЕ</> <text></><text>, чтобы осмотреться.</>",
["Movement.MoveText"] = "<n2>ИСПОЛЬЗУЙТЕ</> <text></><text> для перемещения.</>",
["ReloadMinigame.Title"] = "ПЕРЕГРУЗКА",
["Adrenaline.Title"] = "УРОВНИ АДРЕНАЛИНА",
["AltFire.Title"] = "АЛЬТЕРНАТИВНЫЙ ОГОНЬ",
["AreaScan.Title"] = "СКАНИРОВАНИЕ ОБЛАСТИ",
["Artifacts.Title"] = "АРТЕФАКТЫ",
["Augments.Title"] = "УСИЛИТЕЛИ",
["ReloadMinigame.Text"] = "<n2>НАЖМИТЕ</> <button>{Action_FireTrigger}</>, когда метка перезарядки находится в указанной зоне.\n\nС ее помощью вы можете временно улучшить боевые параметры оружия.",
["Dash.Description"] = "ruTutorial,Dash.Description",
["Adrenaline.Text"] = "Показатель <n1>адреналина</> растет, когда вы уничтожаете врагов, не получая повреждений.\n\nС повышением <n1>уровня адреналина</> открываются особые умения, вы собираете больше оболитов и повышаете <n1>квалификацию</>.",
["LockOn.Description"] = "ruTutorial,LockOn.Description",
["AreaScan.Text"] = "<n2>НАЖМИТЕ</> <button>{Action_EnvironmentScan}</>, чтобы просканировать область и найти выходы.\n\nИспользуйте сканирование и карту, чтобы найти главный путь к цели.",
["Artifacts.Text"] = "<n1>Артефактами</> называются предметы, вызывающие положительные эффекты. Одни действуют сами по себе, другие необходимо активировать.\n\nПросмотреть их можно во вкладке «Снаряжение» <n1>компьютера скафандра</>.",
["Augments.Text"] = "<n1>Усилители</> повышают ваши <n1>характеристики</> на время круга. Они мгновенно применяются к соответствующей <n1>характеристике</> и не хранятся в снаряжении.\n\nДля просмотра характеристик откройте вкладку «Статус» <n1>скафандра компьютера</>.",
["Checkpoint.Title"] = "ruTutorial,Checkpoint.Title",
["Clarity.Title"] = "ЭФИР",
["ConsumableSlot.Title"] = "ЯЧЕЙКИ ДЛЯ РАСХОДНИКОВ",
["Checkpoint.Text"] = "ruTutorial,Checkpoint.Text",
["CursedDiscovery.Text"] = "<n2>Порченые</> предметы с некоторой вероятностью могут вызвать <n2>сбой</> .\n\n<n2>Сбои</> негативно влияют на работу скафандра и даже блокируют некоторые его возможности.",
["CursedDiscovery.Title"] = "ПОРЧЕНЫЕ ПРЕДМЕТЫ",
["Datacube.Title"] = "ruTutorial,Datacube.Title",
["DLC.Title"] = "БАШНЯ СИЗИФА И\nКООП-РЕЖИМ",
["DLC.Description"] = "Теперь вам доступно бесконечное испытание в Башне Сизифа и кооп-режим, позволяющий объединить силы с другим игроком.\n\nОни доступны на месте аварийной посадки.",
["Datacube.Text"] = "ruTutorial,Datacube.Text",
["ExtendedHUD.Title"] = "РАСШИРЕННЫЙ ИНТЕРФЕЙС",
["EyeOfTruth.Title"] = "СКРЫТЫЕ ПЛАТФОРМЫ",
["EyeOfTruth.Text"] = "Стреляйте по светящимся сферам, чтобы увидеть <n1>скрытые платформы</>.",
["PlayGo.Title"] = "ИГРА ЗАГРУЖАЕТСЯ",
["GravityBoots.Title"] = "ПОДВОДНЫЕ ОБЛАСТИ",
["GrindingMachine.Title"] = "ХТОНОС",
["Clarity.Description"] = "<n1>Эфир</>— загадочный ресурс, который не пропадает даже в случае вашей гибели.\n\nЧтобы получить <n1>эфир</>, взаимодействуйте с мертвыми разведчиками и проходите <n1>ежедневные испытания</> на корабле.\n\n<n1>Эфир</> также используется для очищения <n2>порченых</> объектов и применяется в некоторых устройствах.",
["GravityBoots.Text"] = "Теперь ваш скафандр может функционировать <n1>под водой</>.",
["GrindingMachine.text"] = "Это устройство открывает доступ к новым предметам за <n1>эфир</>.\n\nПрогресс отображается на счетчике. Когда индикатор достигнет вершины, вы разблокируете новый предмет.",
["HazardSuit.Title"] = "ОПАСНАЯ СРЕДА",
["PCTutorial.Hold"] = "УДЕРЖИВАЙТЕ",
["HazardSuit.Text"] = "Теперь ваш скафандр защищен от <n1>опасного воздействия среды</>.",
["CoopPermaUpgrades.SubtitleItems"] = "ПРЕДМЕТЫ",
["Jump.Title"] = "ПРЫГНУТЬ",
["Dash.Name"] = "ruTutorial,Dash.Name",
["SusRes.SimpleText"] = "Приостановите цикл в меню игры, чтобы сохранить текущий прогресс.\n\nЕдиновременно у вас может быть только один приостановленный цикл. Данные о приостановке стираются, когда вы возвращаетесь к прохождению.",
["Curse.Title"] = "СБОИ",
["Melee.Title"] = "БЛИЖНИЙ БОЙ",
["MistElevator.Title"] = "ТРАНСЛОКАТОРЫ",
["Movement.Title"] = "ПЕРЕДВИЖЕНИЕ И КАМЕРА",
["MultiRank.Title"] = "РЕЙТИНГ РАЗВЕДЧИКА",
["Curse.Text"] = "<n2>Сбой</>— это негативный эффект, вызванный <n2>порченым</> предметом или <n1>паразитом</>.\n\nДля устранения <n2>сбоя</>  выполните задание в левой части экрана.",
["MistElevator.Text"] = "Теперь ваш скафандр может использовать <n1>транслокаторы</> для телепортирования.",
["PCTutorial.WarningNewControllerTitle"] = "ОБНАРУЖЕН НОВЫЙ КОНТРОЛЛЕР",
["Dash.Title"] = "РЫВОК",
["Hookshot.Title"] = "ИСПОЛЬЗОВАНИЕ КРЮКА",
["Hookshot.Text"] = "<n2>НАЖМИТЕ</> <button>{Action_Interact}</> рядом с целью, чтобы за нее ухватиться.",
["Shoot.Title"] = "ruTutorial,Shoot.Title",
["Shoot.Text"] = "ruTutorial,Shoot.Text",
["Orbs.Title"] = "СИЗИФОВЫ ДАРЫ",
["Parasite.Title"] = "ПАРАЗИТЫ",
["PermaCurseTutorial.Title"] = "НЕОБРАТИМЫЕ СБОИ",
["CoopPermaUpgrades.Title"] = "ПОСТОЯННЫЕ УЛУЧШЕНИЯ",
["Ping.Title"] = "МЕТКА ",
["PCTutorial.Press"] = "НАЖМИТЕ",
["Parasite.Text"] = "<n1>Паразиты</>  и ослабляют, и усиливают ваш скафандр.\n\n<n2>НАЖМИТЕ</> <button>{Action_PauseGame}</>, чтобы просмотреть статус скафандра и информацию о прикрепленных <n1>паразитах</>.",
["PermaCurseTutorial.Text"] = "<n2>Необратимые сбои</> — это отрицательные эффекты, сохраняющиеся на всем продолжении <n2>цикла</>.\n\nОни исчезают только после начала нового <n2>цикла</>. ",
["OrbsDesc.Text"] = "На цветных пьедесталах можно найти полезные предметы. Чтобы активировать их, уничтожьте сферу того же цвета.\n\nНовые сферы появятся, когда вы достигните верхних этажей Башни.",
["Ping.Text"] = "С помощью <n1>метки</> вы можете сообщить другому игроку о важных местах, пунктах назначения или первостепенных целях. При активированной <n1>метке</> в интерфейсах обоих игроков на короткое время отобразится соответствующий ориентир. Можно использовать как на движущихся, так и на неподвижных поверхностях.\n\n\n<button>{Action_Ping}</><n2>НАЖМИТЕ</>, чтобы применить.",
["AltFire.Text2"] = "<n2>НАЖМИТЕ</> <button>{Action_AltFire}</> до упора, чтобы перейти в режим <n1>альтернативного огня</>.",
["AltFire.Text1"] = "<n2>НАЖМИТЕ</> <button>{Action_AltFire}</> наполовину, чтобы прицелиться.",
["ExtendedHUD.Text"] = "<n2>НАЖМИТЕ</> <button>{Action_ToggleExtendedHUD}</>, чтобы показать/скрыть интерфейс. ",
["HelpVideo.Prompt"] = "<n2>НАЖМИТЕ</> <button>{Action_SystemMenu}</> и найдите в меню обучения соответствующее видео.",
["Proficiency.Text"] = "Повышайте <n1>уровень квалификации</>, устраняя врагов.\n\nЧем выше <n1>квалификация</>, тем больше возможностей оружия вам доступно.",
["Roguelike.Title"] = "ЦИКЛ",
["ReviveTutorial.Title"] = "ВОЗРОЖДЕНИЕ",
["Roguelike.Text"] = "С каждой смертью вы возвращаетесь на место крушения без оружия, артефактов и ресурсов, которые получили в предыдущем цикле.\n\n<n1>Записи в хранилище данных</> и <n1>постоянные улучшения</> переходят из цикла в цикл.\n\nИспользуйте постоянные предметы для исследования новых областей и ускорения прохождения.",
["PCTutorial.Scroll"] = "ПРОКРУТИТЕ",
["Ship.Title"] = "ТЕРМИНАЛЫ КОРАБЛЯ",
["Shooting.Title"] = "ПРИМЕНЕНИЕ ОРУЖИЯ",
["CoopPermaUpgrades.SubtitleUpgrades"] = "УСИЛИТЕЛИ СКАФАНДРА",
["SusRes.Title"] = "ПРИОСТАНОВИТЬ И ПРОДОЛЖИТЬ",
["ScoreSystemTutorial.Title"] = "СЧЕТ БАШНИ",
["ScoreSystemTutorialDesc.Text"] = "Вы получаете <n1>баллы</> за зачистку этажей башни.\n\nНе позволяйте своему <n1>множителю счета</> снижаться, быстро проходя игру и поддерживая уровень адреналина.",
["StoryDiary00.Name"] = "ruTutorial,StoryDiary00.Name",
["Ship.Text"] = "У «Гелиоса» два терминала: <n1>основной</> и <n1>терминал испытаний</>.\n\nНа <n1>основном терминале</> можно просмотреть общие игровые показатели и почитать <n1>корабельные журналы</>.\n\nРазблокируйте <n1>терминал испытаний</>, чтобы получить доступ к <n1>ежедневным испытаниям</> для состязаний с другими разведчиками.",
["SuperWeapon.Title"] = "ЭКСТРАКТОРЫ",
["Act3.Title"] = "ЦИКЛ ПРОДОЛЖАЕТСЯ",
["TTChoice.Title"] = "СИЗИФОВ ВЫБОР",
["TTChoice.Text"] = "На определенных этажах находятся фабрикаторы с двойным зарядом.\n\nВам нужно выбрать один из предметов, прежде чем двигаться дальше.",
["LockOn.Name"] = "ruTutorial,LockOn.Name",
["Act3.Text"] = "Чем глубже вы погрузитесь в Returnal, тем больше вас ждет интересных открытий. Для поиска новых сюжетных поворотов используйте устройство в грузовом трюме.",
["CoopPermaUpgrades.EmptyText"] = "В этом цикле пока нет доступных постоянных улучшений.\n\n<button>{action_SystemMenu}</><n2>НАЖМИТЕ</>, чтобы открыть обучение.",
["CoopPermaUpgrades.Text"] = "Эти постоянные улучшения доступны в текущем цикле. Нажмите <n2>{action_PauseGame}</>, чтобы узнать больше, или <button>{action_SystemMenu}</>, чтобы открыть обучение.",
["TutorialIndicator.Text"] = "Анализ ситуации",
["ConsumableSlot.Text"] = "<n2>НАЖМИТЕ</> {Action_PocketLeft} или {Action_PocketRight}, чтобы сменить активную ячейку для расходников.",
["ViewTutorial.Prompt"] = "Открыть обучение",
["Proficiency.Title"] = "ОРУЖЕЙНАЯ КВАЛИФИКАЦИЯ",
["WeaponSystem.Title"] = "ПАРАМЕТРЫ И ОСОБЕННОСТИ ОРУЖИЯ",
["OpenMenu.Title"] = "КОМПЬЮТЕР СКАФАНДРА",
["WeaponSystem.Text"] = "С помощью <n1>квалификации</> можно разблокировать новые особенности и параметры оружия. Чтобы повысить <n1>квалификацию</>, уничтожайте врагов.",
["TetheringTutorial.Title"] = "ПРИВЯЗКА",
["ReviveTutorialDesc.Text"] = "<n1>Павших</> игроков можно <n1>возродить</>. Если другой разведчик <n1>погибает</> до завершения процесса <n1>возрождения</>, то <n1>цикл</> заканчивается.\n\n<button>{Action_Interact}</> <n2>УДЕРЖИВАЙТЕ</>, чтобы <n1>возродить</>.",
["PCTutorial.WarningAdaptiveWithoutDualsense"] = "Вы не используете контроллер DualSense™.\r\n\r\nБез адаптивных триггеров нажать <button>{Action_AltFire}</> наполовину может быть затруднительно.\r\n\r\nРекомендуем переключиться на классическую предустановку контроллера.",
["PCTutorial.WarningDualsenseWithoutAdaptive"] = "Вы используете контроллер DualSense™.\r\n\r\nС адаптивными триггерами будет легко нажать <button>{Action_AltFire}</> наполовину.\r\n\r\nРекомендуем переключиться на адаптивную предустановку контроллера.",
["PlayGo.Text"] = "Вы не можете пройти дальше или включить кооп-режим до загрузки полной версии игры.",
["TetheringTutorialDesc.Text"] = "Если игроки слишком отдалятся друг от друга, они получат предупреждающий сигнал, а потом будут <n1>перемещены</> в одну точку.",
["Consumable.Title"] = "РАСХОДНИКИ",
["StoryDiary00.Description"] = "ruTutorial,StoryDiary00.Description"
},
["Tutorials"] = {
["PCHookshot.Text"] = "<n2>{ActionType_HookShot}</> <button>{Action_HookShot}</> рядом с целью, чтобы за нее ухватиться.",
["PCNominateConsumable.Text"] = "<n2>{ActionType_NominateConsumable}</> <button>{Action_NominateConsumable}</>, чтобы выбрать, какой расходник заменится.",
["PCNominateConsumable.Title"] = "ВЫБРАТЬ РАСХОДНИК",
